import { expect, type Page, type Locator } from '@playwright/test';

export const EXPERT_PATH = '/account/expert';
export const SCENARIOS = ['ראש מתחת למים', 'היעלמות מתחת למים', 'חוסר תנועה', 'תנוחה אנכית במקום', 'עצירה פתאומית'];

/**
 * Предохранитель: все запросы записи (не GET/HEAD/OPTIONS) к supabase отклоняются, кроме /auth/v1/ (обновление сессии).
 * Сохранение правил — rpc save_danger_thresholds (POST); чтение — GET detection_config / detection_config_history.
 * Возвращает журнал: saveCalls — попытки save_danger_thresholds, blocked — все отклонённые запросы.
 */
export async function blockRuleWrites(page: Page) {
  const log = { saveCalls: 0, blocked: [] as string[] };
  await page.route(/supabase\.co\//, async (route) => {
    const req = route.request();
    const m = req.method();
    if (m === 'GET' || m === 'HEAD' || m === 'OPTIONS' || /\/auth\/v1\//.test(req.url())) return route.continue();
    if (/save_danger_thresholds/.test(req.url())) log.saveCalls++;
    log.blocked.push(`${m} ${req.url()}`);
    return route.abort('blockedbyclient');
  });
  return log;
}

/** Открыть экран экспертом и дождаться загрузки текущих значений. */
export async function openExpertScreen(page: Page) {
  await page.goto(EXPERT_PATH);
  await expect(page.getByText('גרסה נוכחית:', { exact: false }).first()).toBeVisible();
  await expect(field(page, 'חוסר תנועה')).not.toHaveValue('');
}

/** Поле ввода под подписью (Expo web: подпись — отдельный div, поле — следующий input). */
export function field(page: Page, label: string): Locator {
  return page.getByText(label, { exact: true }).filter({ visible: true }).first().locator('xpath=following::input[1]');
}

/** Поле «מה נקבע ולמה» (многострочное). */
export function explanation(page: Page): Locator {
  return page.getByText('מה נקבע ולמה', { exact: true }).filter({ visible: true }).first().locator('xpath=following::textarea[1]');
}

export function saveButton(page: Page): Locator {
  return page.getByText('שמירת החוקים', { exact: true }).filter({ visible: true }).last();
}

/** Окно подтверждения сохранения. Если вдруг появилось — тест жмёт «ביטול» (см. cancelConfirmIfShown). */
export function confirmTitle(page: Page): Locator {
  return page.getByText('לשמור את החוקים?', { exact: true });
}

export async function cancelConfirmIfShown(page: Page) {
  if (await confirmTitle(page).isVisible().catch(() => false)) {
    await page.getByText('ביטול', { exact: true }).filter({ visible: true }).last().click();
    await expect(confirmTitle(page)).toBeHidden();
  }
}
